mapper.sql:
CASE WHEN offer.id IS NOT NULL THEN 'ADDED' WHEN spu.status != 0 THEN 'DISABLED' WHEN COUNT(DISTINCT sku.id) = 0 THEN 'DISABLED' WHEN COUNT(DISTINCT CASE WHEN sku.status = 0 THEN sku.id END) = 0 THEN 'DISABLED' WHEN COUNT(DISTINCT CASE WHEN sku.status = 0 AND sku_ext.target_period = #{targetPeriod}
AND grade_rel.grade_catalog_id = #{req.gradeCatalogId}
THEN sku.id END) = 0 THEN 'NO_MATCHED_SKU' ELSE 'CAN_ADD' END

spu.id AS productSpuId, spu.name AS productName, GROUP_CONCAT(DISTINCT category_rel.category_id ORDER BY category_rel.sort, category_rel.category_id) AS categoryIdText, GROUP_CONCAT(DISTINCT category.name ORDER BY category_rel.sort, category.name) AS categoryNameText, spu.pic_url AS picUrl, spu.price AS price, spu.stock AS stock, ext.publisher_id AS publisherId, publisher.name AS publisherName, ext.publication_type_id AS publicationTypeId, publication_type.name AS publicationTypeName, ext.issue_cycle AS issueCycle, CASE WHEN offer.id IS NULL THEN 0 ELSE 1 END AS added, COUNT(DISTINCT sku.id) AS totalSkuCount, COUNT(DISTINCT CASE WHEN sku.status = 0 THEN sku.id END) AS enabledSkuCount, COUNT(DISTINCT CASE WHEN sku.status = 0 AND sku_ext.target_period = #{targetPeriod}
AND grade_rel.grade_catalog_id = #{req.gradeCatalogId}
THEN sku.id END) AS matchedSkuCount, GROUP_CONCAT(DISTINCT CASE WHEN sku.status = 0 AND sku_ext.target_period = #{targetPeriod}
AND grade_rel.grade_catalog_id = #{req.gradeCatalogId}
THEN grade_rel.grade_catalog_id END ORDER BY grade_rel.grade_catalog_id) AS matchedGradeCatalogIdText, AS candidateStatus, spu.status AS productStatus

FROM product_publication_spu_ext ext INNER JOIN product_spu spu ON spu.id = ext.spu_id AND spu.deleted = b'0' AND spu.biz_scene = 'PUBLICATION' INNER JOIN product_spu_category_rel category_rel ON category_rel.spu_id = spu.id AND category_rel.deleted = b'0' INNER JOIN product_category category ON category.id = category_rel.category_id AND category.deleted = b'0' LEFT JOIN product_publisher publisher ON publisher.id = ext.publisher_id AND publisher.deleted = b'0' LEFT JOIN product_publication_type publication_type ON publication_type.id = ext.publication_type_id AND publication_type.deleted = b'0' LEFT JOIN subscription_window_offer offer ON offer.window_id = #{req.windowId} AND offer.product_spu_id = spu.id AND offer.deleted = b'0' LEFT JOIN product_sku sku ON sku.spu_id = spu.id AND sku.deleted = b'0' LEFT JOIN product_publication_sku_ext sku_ext ON sku_ext.sku_id = sku.id AND sku_ext.deleted = b'0' LEFT JOIN product_publication_sku_grade_rel grade_rel ON grade_rel.sku_id = sku.id AND grade_rel.deleted = b'0' WHERE ext.deleted = b'0'
AND ext.publisher_id = #{req.publisherId}
AND ext.publication_type_id = #{req.publicationTypeId}
AND ext.issue_cycle = #{req.issueCycle}
AND spu.name LIKE CONCAT('%', #{req.productName}, '%')
AND EXISTS ( SELECT 1 FROM product_spu_category_rel filter_category_rel WHERE filter_category_rel.spu_id = spu.id AND filter_category_rel.deleted = b'0' AND filter_category_rel.category_id IN
#{categoryId}
)
AND EXISTS ( SELECT 1 FROM product_sku filter_sku INNER JOIN product_publication_sku_grade_rel filter_rel ON filter_rel.sku_id = filter_sku.id AND filter_rel.deleted = b'0' AND filter_rel.grade_catalog_id = #{req.gradeCatalogId} WHERE filter_sku.spu_id = spu.id AND filter_sku.deleted = b'0' )

GROUP BY spu.id, spu.name, spu.pic_url, spu.price, spu.stock, ext.publisher_id, publisher.name, ext.publication_type_id, publication_type.name, ext.issue_cycle, offer.id, spu.status
HAVING candidateStatus = #{req.candidateStatus}
HAVING candidateStatus = 'CAN_ADD'

mapper.select:
SELECT



ORDER BY spu.sort DESC, spu.id DESC

    LIMIT #{limit}

        OFFSET #{offset}
